using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class Rock185Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence185");const string Folder="Assets/Imported185-valid";
 static void Check(bool b,string s){if(!b)throw new Exception(s);}static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.16f,.18f,.2f);RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;}
 static GameObject Prefab(bool before)=>AssetDatabase.LoadAssetAtPath<GameObject>((before?"Assets/Imported137-valid":Folder)+"/small-mine_cut_rock.prefab");
 static string Shape(Mesh m)=>JsonUtility.ToJson(new ShapeData{p=m.vertices,n=m.normals,uv=m.uv,c=m.colors,t=m.triangles});[Serializable]class ShapeData{public Vector3[] p,n;public Vector2[] uv;public Color[] c;public int[] t;}
 public static void Run(){Directory.CreateDirectory(Out);try{Empty();var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
 var data=JsonUtility.FromJson<SmallPropsV1.Data>(File.ReadAllText(Path.Combine(Root,"Input185/small_props.json")));data.mineCutRockV1=MineCutRockV1.Optional(data.mineCutRockV1);Check(data.mineCutRockV1!=null,"formal optional reader accepts final payload");if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder("Assets","Imported185-valid");var parent=new GameObject("formal placement");var prefabs=new Dictionary<string,GameObject>();int placed=MineCutRockV1.Build(Path.Combine(Root,"Input185"),Folder,parent.transform,prefabs,data);Check(prefabs.Count==1&&placed==1,"formal prefab and placement");
 var before=Prefab(true);var after=Prefab(false);var mesh=after.GetComponent<MeshFilter>().sharedMesh;var material=after.GetComponent<Renderer>().sharedMaterial;
 Check(mesh.triangles.Length/3==372&&Shape(mesh)==Shape(before.GetComponent<MeshFilter>().sharedMesh),"all mesh data identical137");Check(after.GetComponentsInChildren<Collider>().Length==1&&ColliderSnapshot109.Capture(after)==ColliderSnapshot109.Capture(before),"actual collider identical137");Check(material.shader.name=="Universal Render Pipeline/Lit"&&material.GetColor("_BaseColor")==Color.white,"formal material");Check(mesh.tangents.Length==mesh.vertexCount&&material.IsKeywordEnabled("_NORMALMAP"),"normal tangent contract");
 foreach(string prop in new[]{"_BaseMap","_MetallicGlossMap","_BumpMap"}){var tex=(Texture2D)material.GetTexture(prop);Check(tex.width==512&&tex.height==256,"same dimensions");var importer=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(tex));Check(importer.sRGBTexture==(prop=="_BaseMap"),"colour space "+prop);if(prop=="_BumpMap")Check(importer.textureType==TextureImporterType.NormalMap,"normal importer");}
 var saved=PrefabUtility.SaveAsPrefabAsset(parent,Folder+"/placement.prefab");UnityEngine.Object.DestroyImmediate(parent);var restored=(GameObject)PrefabUtility.InstantiatePrefab(saved);Check(restored.GetComponentInChildren<Renderer>().sharedMaterial==material&&restored.GetComponentInChildren<MeshFilter>().sharedMesh==mesh,"prefab reinstantiate");var scene=Folder+"/placement.unity";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),scene);Empty();EditorSceneManager.OpenScene(scene);Check(UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Any(x=>x.sharedMaterial==material),"scene reload");
 Studio();Load();AssetDatabase.SaveAssets();Check(!ShaderUtil.ShaderHasError(Shader.Find("Universal Render Pipeline/Lit")),"shader errors");File.WriteAllText(Path.Combine(Out,"checks.json"),"{\"pass\":true,\"formalPrefab\":true,\"meshUVNormals372Unchanged\":true,\"actualColliderUnchanged\":true,\"prefabSceneReload\":true,\"dataMapsLinear\":true,\"player\":false}");var cave=typeof(Rock185Checks).Assembly.GetType("Rock185Cave");if(cave!=null)cave.GetMethod("Run").Invoke(null,null);else EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Studio(){Empty();var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.color=new Color(.24f,.21f,.17f);floor.GetComponent<Renderer>().sharedMaterial=fm;var light=new GameObject("diagnostic sun").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.3f;light.shadows=LightShadows.Soft;var c=new GameObject("offscreen").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.08f,.09f,.1f);c.fieldOfView=45;c.nearClipPlane=.02f;
 foreach(bool before in new[]{true,false}){var rock=(GameObject)PrefabUtility.InstantiatePrefab(Prefab(before));var target=rock.GetComponent<Renderer>().bounds.center;foreach(string v in new[]{"normal","close","opposite","back","dark","point","spot"}){light.enabled=v!="dark"&&v!="point"&&v!="spot";light.transform.rotation=Quaternion.Euler(45,v=="opposite"?60:-30,0);RenderSettings.ambientLight=v=="dark"?Color.black:new Color(.16f,.18f,.2f);Light local=null;if(v=="point"||v=="spot"){local=new GameObject("local").AddComponent<Light>();local.type=v=="spot"?LightType.Spot:LightType.Point;local.transform.position=new Vector3(-1.1f,1.6f,-1.5f);local.transform.LookAt(target);local.range=5;local.intensity=4;local.spotAngle=80;local.shadows=LightShadows.Soft;}c.transform.position=target+(v=="normal"?new Vector3(0,9,-6.3f):v=="back"?new Vector3(-2.2f,1.2f,3):new Vector3(1.3f,1.2f,-3));c.transform.LookAt(target);var img=Shared117Review.Image(c,1600,900);File.WriteAllBytes(Path.Combine(Out,(before?"before-":"after-")+v+".png"),img.EncodeToPNG());UnityEngine.Object.DestroyImmediate(img);if(local)UnityEngine.Object.DestroyImmediate(local.gameObject);}UnityEngine.Object.DestroyImmediate(rock);}}
 [Serializable]class Row{public bool before;public int placed,visible,meshes,materials,textures;public long meshBytes,textureBytes;public double cpuRenderMedianMs;}
 static void Load(){var rows=new List<Row>();foreach(bool before in new[]{true,false})foreach(int count in new[]{9,225}){Empty();var c=new GameObject("load camera").AddComponent<Camera>();c.transform.position=new Vector3(0,30,-24);c.transform.LookAt(Vector3.zero);var root=new GameObject("shared");int side=count==9?3:15;for(int i=0;i<count;i++){var o=(GameObject)PrefabUtility.InstantiatePrefab(Prefab(before),root.transform);o.transform.position=new Vector3((i%side-side/2)*2,0,(i/side-side/2)*2);}var rs=root.GetComponentsInChildren<Renderer>();var ms=root.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).Distinct().ToArray();var mats=rs.Select(x=>x.sharedMaterial).Distinct().ToArray();var tx=mats.SelectMany(m=>new[]{m.GetTexture("_BaseMap"),m.GetTexture("_MetallicGlossMap"),m.GetTexture("_BumpMap")}).Distinct().ToArray();Check(ms.Length==1&&mats.Length==1&&tx.Length==3,"sharing unchanged");var rt=new RenderTexture(640,360,24);rt.Create();c.targetTexture=rt;var times=new List<double>();for(int i=0;i<10;i++){var sw=System.Diagnostics.Stopwatch.StartNew();c.Render();sw.Stop();if(i>=4)times.Add(sw.Elapsed.TotalMilliseconds);}times.Sort();var planes=GeometryUtility.CalculateFrustumPlanes(c);rows.Add(new Row{before=before,placed=count,visible=rs.Count(x=>GeometryUtility.TestPlanesAABB(planes,x.bounds)),meshes=ms.Length,materials=mats.Length,textures=tx.Length,meshBytes=ms.Sum(x=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(x)),textureBytes=tx.Sum(x=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(x)),cpuRenderMedianMs=times[times.Count/2]});c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}Check(rows[0].meshBytes==rows[2].meshBytes&&rows[0].textureBytes==rows[2].textureBytes,"resident estimates unchanged");File.WriteAllText(Path.Combine(Out,"load.json"),"{\"gpuMeasured\":false,\"cpuSubmissionNotFrameGuarantee\":true,\"rows\":["+string.Join(",",rows.Select(x=>JsonUtility.ToJson(x)))+"]}");}
}
